            station_name: defaultStation.station_info.name,
            is_interpolated: false,
            distance_message: '📍 Enable location to get data for your exact position.'
          });
        }
        
        setLastUpdateTime(new Date());
        setError(null); // Clear any location errors if data fetch succeeded

      } catch (fetchError) {
        console.error('❌ Error fetching dashboard data:', fetchError);
        console.log("error fetching");
        
        if (fetchError.name !== 'AbortError') {
          setError('Failed to load dashboard data. Showing sample data.');
          loadSampleData(location); // Pass location to sample data
        }
      } finally {
        setLoading(false);
      }
    };

    // Check for phone number before initializing
    if (phoneNumber) {
      initialize();
    } else {
      // This should not happen, but as a safeguard
      setError("User phone number not found. Please log in again.");
      setLoading(false);
      navigate('/login');
    }
    
    // Cleanup function (no change)
    return () => {
      if (locationTimeoutRef.current) clearTimeout(locationTimeoutRef.current);
      if (abortControllerRef.current) abortControllerRef.current.abort();
    };
  }, [phoneNumber, API_BASE_URL, getUserLocation, loadSampleData, navigate]); // Add new dependencies

  // ===== MEMOIZED VALUES =====
  const currentValues = useMemo(() => currentDataInfo?.values || {}, [currentDataInfo]);
  const currentAQI = useMemo(() => currentDataInfo?.aqi || 50, [currentDataInfo]);
  const aqiStatus = useMemo(() => {
    const aqi = currentAQI;
    if (aqi <= 50) 
    return { status: 'GOOD', color: '#10b981', class: 'good' };

  if (aqi <= 100) 
    return { status: 'SATISFACTORY', color: '#84cc16', class: 'satisfactory' };

  if (aqi <= 200) 
    return { status: 'MODERATE', color: '#facc15', class: 'moderate' };

  if (aqi <= 300) 
    return { status: 'POOR', color: '#f97316', class: 'poor' };

  if (aqi <= 400) 
    return { status: 'VERY POOR', color: '#ef4444', class: 'very-poor' };

  return { status: 'SEVERE', color: '#7c2d12', class: 'severe' };

}, [currentAQI]);

  // ===== LOCATION STATUS COMPONENT =====
  const LocationStatus = useMemo(() => {
    const getLocationDisplay = () => {
      switch (locationStatus) {
        case 'initializing':
          return <span style={{ color: '#6b7280' }}>📍 Initializing location detection...</span>;
        case 'detecting':
          return (
            <span style={{ color: '#f59e0b' }}>
              📍 Detecting your location...
              {isLocationUpdating && <span className="location-spinner">⟳</span>}
            </span>
          );
        // This is the NEW block with the disclaimer
        case 'gps_detected':
          const locationName = userLocationName?.display_name || 'Your location';

          return (
            // Use a div to stack the location and the disclaimer
            <div>
              <span style={{ color: '#10b981' }}>
                  📍 {locationName}
                  {nearestStationInfo && (
                    <span style={{ color: '#6b7280', fontSize: '0.9em' }}>
                        {' '} → Nearest: {nearestStationInfo.name} ({formatDistance(nearestStationInfo.distance)})
                      </span>
                  )}
              </span>
              {/* THIS IS THE NEW DISCLAIMER */}
              <div className="location-disclaimer">
                Note: If your location seems incorrect, it may be due to a slow network. Please refresh the page or check again shortly.
              </div>
            </div>
          );
        case 'failed':
            return null;
        default:
          return <span style={{ color: '#6b7280' }}>📍 </span>;
      }
    };
    return <div className="location-info">{getLocationDisplay()}</div>;
  }, [locationStatus, userLocationName, userLocation, nearestStationInfo, isLocationUpdating, getUserLocation]);

  // ===== UI HELPER FUNCTIONS =====
  const formatValue = useCallback((value, metric) => {
    const numValue = parseFloat(value);
    if (isNaN(numValue)) return '0';
    return metric === 'co' ? numValue.toFixed(1) : Math.round(numValue);
  }, [])

  const metricIcons = useMemo(() => ({
    pm25: '🌱', pm10: '🍃', so2: '🏭', no2: '💨',
    co: '☁️', o3: '☀️', nh3: '⚗️'
  }), []);

  // ===== METRIC CARDS =====
  const MetricCards = useMemo(() => {
    const parameters = ['pm25', 'pm10', 'so2', 'no2', 'co', 'o3', 'nh3'];
    return parameters.map((key) => {
      const value = currentValues[key] || 0;
      return (
        <div key={key} className="metric-card">
          <div className="metric-icon">{metricIcons[key] || '📊'}</div>
          <div className="metric-value">{formatValue(value, key)}</div>
          <div className="metric-label">{key.toUpperCase()}</div>
          <div className="metric-unit">{key === 'co' ? 'mg/m³' : 'µg/m³'}</div>
          {currentDataInfo?.is_interpolated && (<div className="metric-badge interpolated-badge">🎯 Your Location</div>)}
          {!currentDataInfo?.is_interpolated && (<div className="metric-badge nearest-badge">📍 Nearest Station</div>)}
        </div>
      );
    });
  }, [currentValues, metricIcons, formatValue, currentDataInfo]);

  // ===== EVENT HANDLERS =====
  const handleNavLinkClick = useCallback(() => { 
  if (isMobileView) closeMenu(); 
}, [isMobileView, closeMenu]);

  const { logout } = useAuth();

  const handleLogout = useCallback(() => {
    if (isMobileView) closeMenu();
    try {
      // Use centralized logout so we don't accidentally clear unrelated localStorage keys
      logout();
      navigate('/login');
    } catch (error) {
      console.error('Logout error:', error);
      navigate('/login');
    }
  }, [navigate, isMobileView, closeMenu, logout]);



// ===== MEMOIZED VALUES =====
  // ... existing currentValues, currentAQI, and aqiStatus memos ...

  // ADD THIS NEW BLOCK: Calculate the dominant pollutant driving the risk
  const dominantPollutantInfo = useMemo(() => {
    if (!currentValues || Object.keys(currentValues).length === 0) return null;
    
    // CPCB/WHO standard limits for 24-hr/8-hr averages
    const thresholds = { pm25: 60, pm10: 100, so2: 80, no2: 80, co: 2, o3: 100, nh3: 200 };
    let maxRatio = 0;
    let dominant = null;

    Object.keys(thresholds).forEach(key => {
      const val = parseFloat(currentValues[key]) || 0;
      const ratio = val / thresholds[key];
      if (ratio > maxRatio) {
        maxRatio = ratio;
        dominant = key;
      }
    });

    if (!dominant || maxRatio < 0.2) return null; // Only show if there's notable pollution

    const pollutantNames = {
      pm25: 'PM2.5 (Fine Particulates)', pm10: 'PM10 (Coarse Dust)', 
      so2: 'Sulfur Dioxide (SO₂)', no2: 'Nitrogen Dioxide (NO₂)',
      co: 'Carbon Monoxide (CO)', o3: 'Ozone (O₃)', nh3: 'Ammonia (NH₃)'
    };

    return {
      name: pollutantNames[dominant],
      value: currentValues[dominant],
      isHighRisk: maxRatio >= 1
    };
  }, [currentValues]);


  const handleRefreshData = useCallback(async () => {
    const res = await fetchDashboardData(userLocation);
    if (!res) {
      setError('Failed to refresh data. Showing last available data or sample.');
      // Optionally load sample only if no dashboardData exists yet
      if (!dashboardData) loadSampleData(userLocation);
    }
  }, [fetchDashboardData, userLocation, dashboardData, loadSampleData]);

  const handleEnableLocation = useCallback(async () => {
    try {
      const location = await getUserLocation();
      const res = await fetchDashboardData(location);
      if (!res) {
        setError('Failed to fetch personalized data. Showing nearest station or sample.');
        if (!dashboardData) loadSampleData(location);
      }
    } catch (error) {
      console.error('Failed to get location:', error);
      setError('Could not get location. Showing default data.');
      if (!dashboardData) loadSampleData(null);
    }
  }, [getUserLocation, fetchDashboardData, dashboardData, loadSampleData]);

  return (
    <div className="dashboard-page">
      <div className="realtime-status">
        🔴 LIVE • Air Quality Monitoring System Active
      </div>

      {error && (
        <div className="alert-banner severe" style={{ maxWidth: '1400px', margin: '1rem auto' }}>
          ⚠️ {error}
          <button onClick={() => setError(null)} className="error-close" style={{marginLeft: 'auto', background:'none', border:'none', fontSize:'1.2rem', cursor:'pointer'}}>✕</button>
        </div>
      )}

      <nav className="navbar">
        <div className="navbar-content">
          <Link to="/" className="navbar-brand">
            <img src={logoImage} alt="AQM Logo" width={isMobileView ? "32" : "40"} height={isMobileView ? "32" : "40"} />
            AirAware
          </Link>
          <div className="menu-toggle" onClick={toggleMenu} style={{fontSize: '1.5rem', cursor: 'pointer', background:'none', border:'none'}}>
            {isMenuOpen ? '✕' : '☰'}
          </div>
          <ul className={`nav-links ${isMenuOpen ? 'active' : ''}`}>
            <li><Link to="/homepage" className="nav-link" onClick={handleNavLinkClick}>Home</Link></li>
            <li><Link to="/health-assessment" className="nav-link" onClick={handleNavLinkClick}>Health Update</Link></li>
            <li><Link to="/health-report" className="nav-link" onClick={handleNavLinkClick}>Health Report</Link></li>
            <li><Link to="/add-family" className="nav-link" onClick={handleNavLinkClick}>Family</Link></li>
            <li className="user-info">{username}</li>
            <li><button onClick={handleLogout} className="nav-link" style={{color: '#ef4444', fontWeight:'700'}}>Logout</button></li>
          </ul>
        </div>
      </nav>

      <div className={`alert-banner ${aqiStatus.class}`}>
        <span style={{ fontSize: '1.2rem' }}>ℹ️</span> 
        <span>
          <strong>{currentDataInfo?.station_name || 'Your Location'}</strong> AQI: {Math.round(currentAQI)} - {aqiStatus.status}
          {nearestStationInfo && !isMobileView && <span style={{opacity: 0.8, marginLeft: '10px'}}>• Nearest sensor: {formatDistance(nearestStationInfo.distance)}</span>}
        </span>
      </div>

      <div className="main-container">
        <div className="welcome-content">
          <div className="welcome-info">
            <div className="user-avatar">{username.charAt(0).toUpperCase()}</div>
            <div className="welcome-text">
              <h1>Welcome back, {username}</h1>
              {LocationStatus}
            </div>
          </div>
          <div className="aqi-overview">
            <div className="aqi-value" style={{ color: aqiStatus.color }}>{Math.round(currentAQI)}</div>
            <div className="aqi-badge">
              {currentDataInfo?.is_interpolated ? '🎯 Location AQI' : '📍 Station AQI'}
            </div>
            <div style={{ color: 'var(--gray-400)', fontSize: '0.85rem', marginTop: '8px', fontWeight: '500' }}>
              Updated: {lastUpdateTime.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
            </div>
          </div>
        </div>

        <div className="metrics-section">
          <h2 className="section-title">
            Air Quality Metrics
            <small>{currentDataInfo?.is_interpolated ? '(Calculated for your coordinates)' : '(Direct Sensor Data)'}</small>
          </h2>
          <div className="metrics-grid">{MetricCards}</div>
        </div>

        <div className="dashboard-grid">
          <div id="map-section" className="dashboard-card map-card">
            <div className="card-header">
              <h3 className="card-title">Live Sensor Network</h3>
            </div>
            <div className="map-container" style={{ borderRadius: '16px', overflow: 'hidden', height: '350px' }}>
              <React.Suspense fallback={<div style={{padding:'2rem', textAlign:'center', color:'#94a3b8'}}>Loading map...</div>}>
                <LazyMap
                  userLocation={userLocation}
                  stations={dashboardData?.stations}
                  currentAQI={currentAQI}
                  dataType={currentDataInfo?.method || 'default'}
                  nearestStation={nearestStationInfo}
                  userLocationName={userLocationName}
                />
              </React.Suspense>
            </div>
          </div>

          <div className="dashboard-card forecast-card">
            <div className="card-header">
              <h3 className="card-title">4-Day Forecast</h3>
            </div>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {['pm25', 'pm10', 'no2', 'o3', 'so2', 'co', 'nh3'].map(param => (
                <button 
                  key={param} 
                  onClick={() => handleParameterChange(param)}
                  style={{
                    padding: '6px 14px', borderRadius: '20px', border: 'none', fontWeight: '600', cursor: 'pointer',
                    background: selectedParameter === param ? 'var(--gray-900)' : 'var(--gray-100)',
                    color: selectedParameter === param ? 'white' : 'var(--gray-600)',
                    transition: 'all 0.2s'
                  }}
                >
                  {param.toUpperCase()}
                </button>
              ))}
            </div>
            <div className="chart-section" style={{ height: '220px' }}>
              <React.Suspense fallback={<div style={{padding:'2rem', textAlign:'center'}}>Loading chart...</div>}>
                <LazyChart
                  forecastData={nearestStationInfo ? dashboardData?.forecasts?.[nearestStationInfo.id] : dashboardData?.forecasts?.['lora-v1']}
                  selectedParameter={selectedParameter}
                />
              </React.Suspense>
            </div>
          </div>
        </div>

        {healthData && (
          <div className="health-section">
            <div className="card-header"><h3 className="card-title" style={{fontSize: '1.8rem'}}>Health Status Monitor</h3></div>
            <div className="health-content">
              <div className="health-display">
                <div className="health-score-circle">
                  <div className="health-score-value">{healthData.score}</div>
                  <div className="health-score-label">Score</div>
                </div>
                <div className="health-details">
                  <div className={`risk-level ${healthData.risk_level.toLowerCase()}`}>{healthData.risk_level} Risk</div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    {Array.isArray(healthData.recommendations)
                      ? healthData.recommendations.map((rec, index) => (
                          <div key={index} style={{color: 'var(--gray-600)', fontWeight: '500'}}>• {rec}</div>
                        ))
                      : <div style={{color: 'var(--gray-600)', fontWeight: '500'}}>• {String(healthData.recommendations)}</div>}
                  </div>
                </div>
              </div>
              
              <div className="health-advisory">
                <h3 style={{fontSize: '1.2rem', marginBottom: '15px', color: 'var(--gray-900)', fontWeight: '800'}}>Health Advisory</h3>
                
                {dominantPollutantInfo && (
                  <div style={{
                    marginBottom: '20px', padding: '16px', borderRadius: '12px',
                    background: dominantPollutantInfo.isHighRisk ? '#fef2f2' : '#fffbeb',
                    border: `1px solid ${dominantPollutantInfo.isHighRisk ? '#fca5a5' : '#fde047'}`
                  }}>
                    <strong style={{ color: dominantPollutantInfo.isHighRisk ? '#991b1b' : '#92400e', display: 'block', fontSize: '1.05rem' }}>
                      ⚠️ Primary Pollutant Concern: {dominantPollutantInfo.name}
                    </strong>
                    <p style={{ marginTop: '6px', fontSize: '0.95rem', color: 'var(--gray-700)' }}>
                      {dominantPollutantInfo.isHighRisk
                        ? `Levels are currently exceeding safe limits, directly increasing your respiratory risk level.`
                        : `Elevated levels are currently the main contributor to the air quality risk in your area.`}
                    </p>
                  </div>
                )}

                <p style={{ color: 'var(--gray-600)', lineHeight: '1.6' }}>People with asthma, heart disease, older adults, and young children are more susceptible to air pollution. Please follow health advisories closely and seek medical attention if you experience adverse symptoms.</p>
                {healthData.risk_level === 'High' && <div style={{marginTop: '15px', padding: '12px', background: '#fee2e2', color: '#b91c1c', borderRadius: '8px', fontWeight: '700'}}>Emergency Contact: Kerala Pollution Control Board – 0471-2418566</div>}
              </div>
            </div>
          </div>
        )}

        <div style={{ marginTop: '3rem' }}>
          <h2 className="section-title">Local Weather</h2>
          <div className="weather-grid">
            <div className="weather-card"><div className="weather-icon">🌡️</div><div className="weather-value">{formatValue(currentValues.temp || 28, 'temp')}°C</div><div className="metric-label">Temperature</div></div>
            <div className="weather-card"><div className="weather-icon">💧</div><div className="weather-value">{formatValue(currentValues.hum || 65, 'hum')}%</div><div className="metric-label">Humidity</div></div>
            <div className="weather-card"><div className="weather-icon">🧭</div><div className="weather-value">{formatValue(currentValues.pre || 1013, 'pre')} hPa</div><div className="metric-label">Pressure</div></div>
          </div>
        </div>               
      </div>

      <footer className="footer">
        <div className="main-container" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '3rem', padding: '0' }}>
          <div>
            <h4>AirAware Kerala</h4>
            <p style={{color: 'var(--gray-500)', marginTop: '10px'}}>Smart Air Quality Monitoring System leveraging IoT and AI to provide real-time environmental intelligence.</p>
          </div>
          <div>
            <h4>Quick Links</h4>
            <ul style={{ listStyle: 'none', marginTop: '10px', lineHeight: '2' }}>
              <li><Link to="/homepage" style={{color: 'var(--gray-400)', textDecoration: 'none'}}>Home</Link></li>
              <li><Link to="/health-report" style={{color: 'var(--gray-400)', textDecoration: 'none'}}>Health Report</Link></li>
            </ul>
          </div>
          <div>
            <h4>Contact</h4>
            <p style={{color: 'var(--gray-500)', marginTop: '10px'}}>
              Center for AI & IoT Innovation<br/>
              Adi Shankara Institute<br/>
              aiiot@adishankara.ac.in
            </p>
          </div>
        </div>
      </footer>
    </div>
  );
}

export default Dashboard;
